# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the app's "desktop": this machine's wallpaper, shown when no panel is open
#          (ui.desktop). BACKGROUND is the one place that says which file that is: Omarchy's
#          link to the current theme's background, so the app follows the desktop around it.
#          Read from disk on every request (no cache): a theme change shows on the next reload.
# Usage: GET /background (mounted in api.py) -> the picture, or 404 when this machine has none
#        (the view then keeps its plain dark background).
# ---------------------------------------------------------------------------
from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING

from starlette.responses import FileResponse, Response

if TYPE_CHECKING:
    from starlette.requests import Request

# This machine's wallpaper. Omarchy repoints this link when the theme or background changes
# (today: the Everforest theme's 1-tree-tops.webp). Another picture: change the path here.
BACKGROUND: Path = Path.home() / ".local/state/omarchy/current/background"


async def background(_: Request) -> Response:
    """The wallpaper as it is now; 404 when there is none (not Omarchy, or a broken link)."""
    picture = BACKGROUND.resolve()
    if not picture.is_file():
        return Response(status_code=404)
    # no-store: the browser asks again each time, so it never shows an old theme's picture
    return FileResponse(picture, headers={"Cache-Control": "no-store"})
